    "framework": null,
    "language": null,
    "text": {
      "uz": "To‘lov yuborildi, lekin javob kutish vaqti tugadi (timeout). Foydalanuvchi yana to‘lashni bosdi. Pul ikki marta yechilmasligini qanday tekshirasiz?",
      "ru": "Запрос оплаты отправлен, но время ожидания ответа истекло. Пользователь нажал оплату ещё раз. Как проверить, что деньги не спишутся дважды?",
      "en": "A payment request times out and the user clicks Pay again. How would you verify that the user is not charged twice?"
    },
